+import { revalidateTag, unstable_cacheTag as cacheTag } from "next/cache";
+import { getAllProducts } from "../lib/db";
+
+type Product = {
+  id: number;
+  name: string;
+  price: number;
+};
+
+async function ProductList() {
+  "use cache";
+  cacheTag("products");
+
+  const products = (await getAllProducts()) as Product[];
+
+  return (
+    <ul>
+      {products.map((product) => (
+        <li key={product.id}>
+          {product.name} - ${product.price}
+        </li>
+      ))}
+    </ul>
+  );
+}
+
 export default function Page() {
   return (
-    <div>
-      <h1>Home</h1>
-    </div>
+    <main>
+      <h1>Product Listing</h1>
+      <p>Submit to invalidate only the products cache tag after data updates.</p>
+      <form
+        action={async () => {
+          "use server";
+          // Pattern: perform your DB mutation first, then invalidate affected tags only.
+          revalidateTag("products");
+        }}
+      >
+        <button type="submit">Invalidate Products Cache</button>
+      </form>
+      <ProductList />
+    </main>
   );
 }
